    public static void publishChanges(MinecraftServer server, UUID ownerUuid, PlayerCompanionData before, PlayerCompanionData after, Set<UUID> changedUuids, long beforeRevision, long afterRevision) {
        if (server == null || ownerUuid == null || before == null || after == null || changedUuids == null || changedUuids.isEmpty() || beforeRevision == afterRevision) {
