        boolean newDead = after.deadList().contains(uuid);
        if (!oldRegistered && !oldDead && newRegistered) {
            result.add(CompanionLifecycleEvent.Change.REGISTERED);
        }
        if (oldRegistered && newDead) {
            result.add(CompanionLifecycleEvent.Change.DIED);
        }
