            result.add(CompanionLifecycleEvent.Change.RELEASED);
        }
        if (newRegistered) {
            CompanionLifecycleState oldState = oldRegistered ? before.lifecycleState(uuid) : null;
            CompanionLifecycleState newState = after.lifecycleState(uuid);
            if (newState != oldState) {
                if (newState == CompanionLifecycleState.DEPLOYED) {
                    result.add(CompanionLifecycleEvent.Change.DEPLOYED);
                }
                if (newState == CompanionLifecycleState.STORED || newState == CompanionLifecycleState.HOME_STORED) {
                    result.add(CompanionLifecycleEvent.Change.STORED);
                }
                result.add(CompanionLifecycleEvent.Change.LIFECYCLE_CHANGED);
            }
        }
        boolean oldHome = before.homeHouseId(uuid).isPresent() || before.homeNestBlock(uuid).isPresent();
        boolean bl = newHome = after.homeHouseId(uuid).isPresent() || after.homeNestBlock(uuid).isPresent();
        if (!oldHome && newHome) {
            result.add(CompanionLifecycleEvent.Change.HOME_ASSIGNED);
        }
        if (oldHome && !newHome) {
            result.add(CompanionLifecycleEvent.Change.HOME_CLEARED);
        }
        if (oldHome && newHome && (!before.homeHouseId(uuid).equals(after.homeHouseId(uuid)) || !before.homeNestBlock(uuid).equals(after.homeNestBlock(uuid)))) {
            result.add(CompanionLifecycleEvent.Change.HOME_CHANGED);
        }
        return result;
    }
}

