        Transaction active = activeKey == null ? null : ACTIVE.get(activeKey);
        return active != null && active.action == CompanionAction.SELECT_SUMMON && active.targetUuid.equals(targetUuid);
    }

    public static void reject(ServerPlayer player, UUID requestId, CompanionKind kind, CompanionAction action, UUID targetUuid, String reason) {
