        CompanionWheelTransactionService.finish(player, new Transaction(requestId, player.m_20148_(), kind, action, targetUuid, CompanionDataService.revision(player), false, player.m_284548_().m_46467_()), WheelIntentPhase.REJECTED, reason);
    }

    public static void completeImmediate(ServerPlayer player, UUID requestId, String reason) {
